    AUTH_FORGOT_PASSWORD = `import { useState, type FormEvent } from "react";
import { ArrowLeft, MailCheck, Loader2 } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuth } from "@/integrations/backend/auth";

/**
 * Forgot-password flow with success confirmation state.
 *
 * Wired to \`useAuth().resetPasswordForEmail\`, which sends an email linking
 * back to \`/reset-password\` \u2014 make sure that route is mounted (see
 * \`auth-reset-password.tsx\` in this folder).
 */
export default function ForgotPassword() {
  const { resetPasswordForEmail } = useAuth();
  const [email, setEmail] = useState("");
  const [sent, setSent] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setLoading(true);
    setErrorMsg(null);
    const { error } = await resetPasswordForEmail(email);
    setLoading(false);
    if (error) {
      setErrorMsg(error.message);
      return;
    }
    setSent(true);
  }

  return (
    <div className="flex min-h-screen items-center justify-center px-4 py-12">
      <Card className="w-full max-w-sm">
        <CardHeader>
          <a href="/" className="mb-2 inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground">
            <ArrowLeft className="h-3 w-3" /> Back to sign in
          </a>
          <CardTitle>Reset your password</CardTitle>
          <CardDescription>
            We'll email you a link to set a new password.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {sent ? (
            <div className="flex items-start gap-3 rounded-lg border border-border bg-muted/40 p-3 text-sm">
              <MailCheck className="mt-0.5 h-4 w-4 shrink-0 text-primary" />
              <div>
                <p className="font-medium">Check your inbox</p>
                <p className="text-xs text-muted-foreground">
                  If an account exists for that email, a reset link is on the way.
                </p>
              </div>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-3">
              <div className="space-y-1.5">
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="you@company.com"
                  required
                />
              </div>
              {errorMsg && <p className="text-xs text-destructive">{errorMsg}</p>}
              <Button type="submit" className="w-full" disabled={loading}>
                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Send reset link
              </Button>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
`;
    AUTH_RESET_PASSWORD = `import { useEffect, useState, type FormEvent } from "react";
import { Lock, Loader2, CheckCircle2 } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuth } from "@/integrations/backend/auth";

/**
 * /reset-password landing page.
 *
 * The recovery email from \`resetPasswordForEmail\` links here with an
 * active recovery session already in the URL hash. AuthProvider picks it
 * up automatically; this page just collects a new password and calls
 * \`updatePassword\`.
 *
 * Mount this at the public route \`/reset-password\` (it must NOT be
 * behind your auth gate).
 */
export default function ResetPassword() {
  const { updatePassword, session, loading: authLoading } = useAuth();
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  useEffect(() => {
    if (!authLoading && !session) {
      setErrorMsg("This reset link has expired. Request a new one.");
    }
  }, [authLoading, session]);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (password.length < 8) {
      setErrorMsg("Password must be at least 8 characters.");
      return;
    }
    if (password !== confirm) {
      setErrorMsg("Passwords don't match.");
      return;
    }
    setSubmitting(true);
    setErrorMsg(null);
    const { error } = await updatePassword(password);
    setSubmitting(false);
    if (error) {
      setErrorMsg(error.message);
      return;
    }
    setDone(true);
    setTimeout(() => {
      window.location.assign("/");
    }, 1500);
  }

  return (
    <div className="flex min-h-screen items-center justify-center px-4 py-12">
      <Card className="w-full max-w-sm">
        <CardHeader>
          <CardTitle>Set a new password</CardTitle>
          <CardDescription>
            Choose a strong password you haven't used before.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {done ? (
            <div className="flex flex-col items-center gap-3 py-4 text-center">
              <CheckCircle2 className="h-8 w-8 text-primary" />
              <p className="text-sm font-medium">Password updated</p>
              <p className="text-xs text-muted-foreground">Redirecting\u2026</p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-3">
              <div className="space-y-1.5">
                <Label htmlFor="password">New password</Label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    id="password"
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="At least 8 characters"
                    minLength={8}
                    className="pl-9"
                    required
                  />
                </div>
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="confirm">Confirm password</Label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    id="confirm"
                    type="password"
                    value={confirm}
                    onChange={(e) => setConfirm(e.target.value)}
                    minLength={8}
                    className="pl-9"
                    required
                  />
                </div>
              </div>
              {errorMsg && <p className="text-xs text-destructive">{errorMsg}</p>}
              <Button type="submit" className="w-full" disabled={submitting || authLoading || !session}>
                {submitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Update password
              </Button>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
`;
