    KIT_MULTI_PAGE_APP = `import { Router, Routes, Route, Outlet, NavLink, Link, useParams } from "@/components/ui/router";
import { Container } from "@/components/ui/container";
import { Inline } from "@/components/ui/inline";
import { Stack } from "@/components/ui/stack";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { cn } from "@/lib/utils";

/**
 * Canonical multi-page app pattern. Copy this into App.tsx as the starting
 * point for ANY app with more than one screen. Add new <Route> entries and
 * \`src/pages/<Name>.tsx\` files as needed.
 *
 * Key rules:
 * - One <Router> per app (never nested).
 * - Shared chrome lives inside a layout route via <Outlet />.
 * - <NavLink> in the header gives free active styling.
 * - <Link> for navigation (NEVER <a href>) \u2014 preserves SPA routing.
 * - useParams() for dynamic segments like /post/:slug.
 */

function SiteHeader() {
  return (
    <header className="border-b border-border bg-background/80 backdrop-blur sticky top-0 z-40">
      <Container>
        <Inline justify="between" align="center" className="h-14">
          <Link to="/" className="font-semibold text-foreground">Acme</Link>
          <Inline gap={1}>
            {[
              { to: "/", label: "Home", end: true },
              { to: "/posts", label: "Posts" },
              { to: "/about", label: "About" },
            ].map((link) => (
              <NavLink
                key={link.to}
                to={link.to}
                end={link.end}
                className={({ isActive }) =>
                  cn(
                    "px-3 py-1.5 rounded-md text-sm transition-colors",
                    isActive
                      ? "bg-accent text-accent-foreground"
                      : "text-muted-foreground hover:text-foreground hover:bg-accent/50",
                  )
                }
              >
                {link.label}
              </NavLink>
            ))}
          </Inline>
        </Inline>
      </Container>
    </header>
  );
}

function SiteLayout() {
  return (
    <div className="min-h-screen bg-background text-foreground">
      <SiteHeader />
      <main>
        <Outlet />
      </main>
    </div>
  );
}

function HomePage() {
  return (
    <Container className="py-16">
      <Stack gap={4}>
        <h1 className="text-4xl font-semibold tracking-tight">Welcome</h1>
        <p className="text-muted-foreground">
          A tiny multi-page app showing the canonical Kimble routing pattern.
        </p>
        <Inline gap={3}>
          <Button asChild><Link to="/posts">Read posts</Link></Button>
          <Button variant="outline" asChild><Link to="/about">About us</Link></Button>
        </Inline>
      </Stack>
    </Container>
  );
}

const POSTS = [
  { slug: "hello-world", title: "Hello, world", excerpt: "Our very first post." },
  { slug: "design-systems", title: "On design systems", excerpt: "Why constraints help you ship." },
  { slug: "ship-it", title: "Ship it", excerpt: "Done is better than perfect." },
];

function PostsPage() {
  return (
    <Container className="py-16">
      <Stack gap={4}>
        <h1 className="text-3xl font-semibold tracking-tight">Posts</h1>
        <Stack gap={3}>
          {POSTS.map((p) => (
            <Card key={p.slug} className="hover:border-foreground/20 transition-colors">
              <CardHeader>
                <CardTitle>
                  <Link to={\`/post/\${p.slug}\`} className="hover:underline">{p.title}</Link>
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-muted-foreground">{p.excerpt}</p>
              </CardContent>
            </Card>
          ))}
        </Stack>
      </Stack>
    </Container>
  );
}

function PostDetailPage() {
  const { slug } = useParams<{ slug: string }>();
  const post = POSTS.find((p) => p.slug === slug);
  return (
    <Container className="py-16">
      <Stack gap={4}>
        <Link to="/posts" className="text-sm text-muted-foreground hover:text-foreground">&larr; Back to posts</Link>
        <h1 className="text-3xl font-semibold tracking-tight">{post?.title ?? "Not found"}</h1>
        <p className="text-muted-foreground">{post?.excerpt ?? "We couldn't find that post."}</p>
      </Stack>
    </Container>
  );
}

function AboutPage() {
  return (
    <Container className="py-16">
      <Stack gap={4}>
        <h1 className="text-3xl font-semibold tracking-tight">About</h1>
        <p className="text-muted-foreground">Acme builds tools that help teams ship faster.</p>
      </Stack>
    </Container>
  );
}

function NotFoundPage() {
  return (
    <Container className="py-24">
      <Stack gap={4} align="center">
        <h1 className="text-4xl font-semibold tracking-tight">404</h1>
        <p className="text-muted-foreground">That page doesn't exist.</p>
        <Button asChild><Link to="/">Go home</Link></Button>
      </Stack>
    </Container>
  );
}

export default function App() {
  return (
    <Router>
      <Routes>
        <Route element={<SiteLayout />}>
          <Route path="/" element={<HomePage />} />
          <Route path="/posts" element={<PostsPage />} />
          <Route path="/post/:slug" element={<PostDetailPage />} />
          <Route path="/about" element={<AboutPage />} />
          <Route path="*" element={<NotFoundPage />} />
        </Route>
      </Routes>
    </Router>
  );
}
`;
    EXAMPLES_INDEX = `# Examples pack \u2014 copy-from reference patterns

These files are NOT imported by App.tsx. They exist purely as a high-quality
source of patterns the AI can read and adapt. When the user asks for a
"sign-in screen", "pricing page", "team members table", etc., open the
matching file below and adapt \u2014 do not invent layouts from scratch.

## Auth
- \`auth-sign-in-card.tsx\` \u2014 centered sign-in with email/password + OAuth
- \`auth-sign-up-split.tsx\` \u2014 split-screen onboarding (brand left, form right)
- \`auth-forgot-password.tsx\` \u2014 (backend projects only) reset request form (calls \`resetPasswordForEmail\`)
- \`auth-reset-password.tsx\` \u2014 (backend projects only) landing page for the reset link (calls \`updatePassword\`); mount at \`/reset-password\`
- \`auth-otp-card.tsx\` \u2014 six-digit code verification

## Auth modals (Dialog / Sheet)
- \`auth-sign-up-dialog.tsx\` \u2014 modal sign-up (controlled, OAuth + switch to sign-in)
- \`auth-sign-in-dialog.tsx\` \u2014 modal sign-in (controlled, hooks for forgot/sign-up)
- \`auth-password-reset-sheet.tsx\` \u2014 side-sheet password reset with success state
- \`auth-magic-link-dialog.tsx\` \u2014 passwordless modal with magic-link success state

## Onboarding flow (composed from auth blocks)
- \`onboarding-welcome.tsx\` \u2014 hero/welcome screen with primary + secondary CTAs
- \`onboarding-signup-step.tsx\` \u2014 name + email + password step (calls \`onSubmit\`)
- \`onboarding-verify-step.tsx\` \u2014 six-digit OTP step bound to the signup email
- \`onboarding-success.tsx\` \u2014 final "you're all set" screen
- \`onboarding-flow.tsx\` \u2014 (backend projects only) orchestrator wiring welcome \u2192 signup \u2192 verify \u2192 done, with forgot-password side route

## Dashboard
- \`dashboard-stats-grid.tsx\` \u2014 four-up KPI cards with delta indicators
- \`dashboard-sidebar-layout.tsx\` \u2014 persistent left rail + top bar shell
- \`dashboard-chart-card.tsx\` \u2014 analytics card with range tabs + sparkline
- \`dashboard-activity-feed.tsx\` \u2014 vertical timeline of team events
- \`dashboard-empty-state.tsx\` \u2014 friendly empty list/table block

## Dashboard widgets (combinable atoms)
- \`widget-kpi-card.tsx\` \u2014 single KPI tile, prop-driven (label/value/delta/icon)
- \`widget-filter-bar.tsx\` \u2014 search + segment tabs + date range + actions toolbar
- \`widget-chart-area.tsx\` \u2014 area-chart card placeholder (pure SVG, swap for recharts)
- \`widget-chart-bar.tsx\` \u2014 bar-chart card placeholder (pure SVG)
- \`widget-chart-donut.tsx\` \u2014 donut chart with inline legend (pure SVG)
- \`widget-activity-log.tsx\` \u2014 compact log-style feed (info/success/warn/commit)
- \`widget-table-sortable.tsx\` \u2014 generic sortable + selectable data table

## Pricing
- \`pricing-three-tier.tsx\` \u2014 three-plan grid with featured tier
- \`pricing-toggle-billing.tsx\` \u2014 monthly / annual toggle
- \`pricing-comparison-table.tsx\` \u2014 side-by-side feature matrix

## Hero
- \`hero-centered-gradient.tsx\` \u2014 centered marketing hero with gradient
- \`hero-split-screenshot.tsx\` \u2014 copy left, product mock right
- \`hero-logo-cloud.tsx\` \u2014 social-proof logo strip
- \`hero-feature-band.tsx\` \u2014 four-up feature row below the hero

## Forms
- \`form-profile-settings.tsx\` \u2014 avatar + name + bio settings card
- \`form-multi-step.tsx\` \u2014 three-step onboarding wizard with progress
- \`form-contact.tsx\` \u2014 public contact form with reason select
- \`form-inline-validation.tsx\` \u2014 live password-strength meter

## Tables
- \`table-users-list.tsx\` \u2014 team table with avatar, role badge, actions menu
- \`table-invoices.tsx\` \u2014 billing history with status badges + download
- \`table-filter-toolbar.tsx\` \u2014 search + status filter + primary CTA above
- \`table-paginated.tsx\` \u2014 sortable header + pagination footer

## Variants \u2014 forms & tables
- \`table-inline-edit.tsx\` \u2014 click-to-edit row with Save/Cancel controls
- \`table-destructive-confirm.tsx\` \u2014 delete row with type-to-confirm AlertDialog guard
- \`form-multi-step-error.tsx\` \u2014 wizard with submit failure: inline alert, retry, recover-to-step

## Kit expansion demos (Phase 3)
- \`kit-validated-form.tsx\` \u2014 useForm + FormField + Combobox + DatePicker with inline validation
- \`kit-sales-chart-card.tsx\` \u2014 revenue card with Tabs switching between Area / Line / Bar charts

## AI image placeholders (Phase 4)
- \`kit-ai-image-hero.tsx\` \u2014 full-bleed hero with an AI-generated background via \`petal-image://\`
- \`kit-ai-image-gallery.tsx\` \u2014 three-card product gallery, each tile a unique AI-generated image

## Multi-page routing (Phase 5)
- \`kit-multi-page-app.tsx\` \u2014 canonical App.tsx with Router/Routes/Route, shared layout via Outlet, NavLink active states, dynamic \`/post/:slug\`, and a 404 catch-all. Copy this when the user wants more than one page.

## Fintech / Web3 (key-gated, read-only \u2014 DO NOT use unless the user has provided keys)
- \`fintech-viem-readonly.tsx\` \u2014 read-only EVM balance lookup with viem + an Alchemy/Infura RPC URL. NEVER signs or sends transactions. Requires \`VITE_ALCHEMY_RPC_URL\`.
- \`fintech-plaid-link.tsx\` \u2014 Plaid Link launcher loaded from CDN. Requires backend routes \`/api/plaid/link-token\` + \`/api/plaid/exchange\` using server-side \`PLAID_CLIENT_ID\` + \`PLAID_SECRET\`. NEVER ship Plaid secrets to the client.


## Conventions

- Every example uses semantic tokens only \u2014 no raw hex, no Tailwind colour names.
- Every example is self-contained: one default export, no router, no fetching.
- When adapting, keep the structure but rename, restyle copy, and wire data.
- Never import these files from App.tsx or routes \u2014 they are reference-only.
`;
    FINTECH_VIEM_READONLY = `import { useEffect, useState } from "react";
import { createPublicClient, http, formatEther } from "viem";
import { mainnet } from "viem/chains";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

/**
 * READ-ONLY EVM balance lookup using viem. Safe for browser/edge.
 * Requires VITE_ALCHEMY_RPC_URL (or any HTTPS RPC). NEVER put a private
 * key in client code. NEVER sign or send transactions from the browser.
 *
 * Adapt by passing the address as a prop. Do not generalize this into
 * a custodial wallet \u2014 Kimble does not support custody.
 */
export default function ViemReadOnlyBalance({ address }: { address: \`0x\${string}\` }) {
  const [eth, setEth] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const rpc = import.meta.env.VITE_ALCHEMY_RPC_URL as string | undefined;
    if (!rpc) {
      setError("Missing VITE_ALCHEMY_RPC_URL \u2014 add an RPC URL to enable on-chain reads.");
      return;
    }
    const client = createPublicClient({ chain: mainnet, transport: http(rpc) });
    client
      .getBalance({ address })
      .then((wei) => setEth(formatEther(wei)))
      .catch((e: Error) => setError(e.message));
  }, [address]);

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-base">On-chain balance (read-only)</CardTitle>
      </CardHeader>
      <CardContent>
        {error ? (
          <p className="text-sm text-destructive">{error}</p>
        ) : eth === null ? (
          <p className="text-sm text-muted-foreground">Loading\u2026</p>
        ) : (
          <p className="text-2xl font-semibold tabular-nums">{Number(eth).toFixed(4)} ETH</p>
        )}
        <p className="mt-2 text-xs text-muted-foreground">
          Read-only via Alchemy/Infura RPC. No keys, no signing.
        </p>
      </CardContent>
    </Card>
  );
}
`;
    FINTECH_PLAID_LINK_BUTTON = `import { useCallback, useEffect, useState } from "react";
import { Button } from "@/components/ui/button";

/**
 * Plaid Link launcher. Requires:
 *   - A backend route POST /api/plaid/link-token that returns { link_token }
 *     using PLAID_CLIENT_ID + PLAID_SECRET (server-side only \u2014 NEVER ship
 *     these to the browser).
 *   - A backend route POST /api/plaid/exchange that exchanges public_token
 *     for an access_token and stores it server-side.
 *
 * Loads Plaid Link from the official CDN to avoid bundling a Node-only
 * SDK in the browser. Adapt onSuccess to call your exchange endpoint.
 */
declare global {
  interface Window {
    Plaid?: {
      create: (opts: {
        token: string;
        onSuccess: (publicToken: string, metadata: unknown) => void;
        onExit?: (err: unknown, metadata: unknown) => void;
      }) => { open: () => void };
    };
  }
}

export default function PlaidLinkButton() {
  const [linkToken, setLinkToken] = useState<string | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const id = "plaid-link-script";
    if (document.getElementById(id)) {
      setReady(true);
      return;
    }
    const s = document.createElement("script");
    s.id = id;
    s.src = "https://cdn.plaid.com/link/v2/stable/link-initialize.js";
    s.onload = () => setReady(true);
    document.body.appendChild(s);
  }, []);

  useEffect(() => {
    fetch("/api/plaid/link-token", { method: "POST" })
      .then((r) => r.json())
      .then((j: { link_token?: string }) => setLinkToken(j.link_token ?? null))
      .catch(() => setLinkToken(null));
  }, []);

  const open = useCallback(() => {
    if (!linkToken || !window.Plaid) return;
    const handler = window.Plaid.create({
      token: linkToken,
      onSuccess: async (publicToken) => {
        await fetch("/api/plaid/exchange", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ public_token: publicToken }),
        });
      },
    });
    handler.open();
  }, [linkToken]);

  return (
    <Button onClick={open} disabled={!ready || !linkToken}>
      {ready && linkToken ? "Connect a bank account" : "Loading\u2026"}
    </Button>
  );
}
`;
