    STAT = `import * as React from "react";
import { ArrowDownRight, ArrowUpRight, Minus } from "lucide-react";
import { cn, slotNode } from "@/lib/utils";

/**
 * Single KPI atom. Compose into a Grid for stat bands.
 *   <Stat label="MRR" value="$48,210" delta={12.4} />
 */
export function Stat({
  label,
  value,
  delta,
  hint,
  className,
}: {
  label: string;
  value: React.ReactNode;
  /** Percentage change. Positive = up, negative = down, 0/null = flat. */
  delta?: number | null;
  hint?: string;
  className?: string;
}) {
  const dir = delta == null ? "flat" : delta > 0 ? "up" : delta < 0 ? "down" : "flat";
  const Icon = dir === "up" ? ArrowUpRight : dir === "down" ? ArrowDownRight : Minus;
  const tone =
    dir === "up"
      ? "text-emerald-600 dark:text-emerald-400"
      : dir === "down"
        ? "text-rose-600 dark:text-rose-400"
        : "text-muted-foreground";
  return (
    <div className={cn("rounded-xl border border-border bg-card p-5", className)}>
      <div className="text-xs font-medium uppercase tracking-wide text-muted-foreground">{label}</div>
      <div className="mt-2 text-3xl font-semibold tracking-tight text-foreground">{value}</div>
      {(delta != null || hint) && (
        <div className="mt-2 flex items-center gap-1 text-xs">
          {delta != null && (
            <span className={cn("inline-flex items-center gap-0.5 font-medium", tone)}>
              <Icon className="h-3 w-3" />
              {Math.abs(delta).toFixed(1)}%
            </span>
          )}
          {hint && <span className="text-muted-foreground">{hint}</span>}
        </div>
      )}
    </div>
  );
}
`;
