    FOOTER_COLUMNS = `import * as React from "react";
import { Container } from "@/components/ui/container";
import { Github, Twitter, Instagram, Facebook, Linkedin, Youtube, Globe, Mail, Circle } from "lucide-react";
import { cn, slotNode } from "@/lib/utils";

export interface FooterColumn {
  title: string;
  links: { label: string; href: string }[];
}

type SocialEntry = {
  href: string;
  label?: string;
  icon?: React.ComponentType<{ className?: string }> | React.ReactNode;
  platform?: string;
};

const PLATFORM_ICONS: Record<string, React.ComponentType<{ className?: string }>> = {
  github: Github,
  twitter: Twitter,
  x: Twitter,
  instagram: Instagram,
  facebook: Facebook,
  linkedin: Linkedin,
  youtube: Youtube,
  web: Globe,
  website: Globe,
  email: Mail,
  mail: Mail,
};

function renderSocialIcon(s: SocialEntry): React.ReactNode {
  // \`icon\` may be a component (\`icon: Twitter\`) or an element (\`icon: <Twitter />\`).
  if (typeof s.icon === "function") {
    const Icon = s.icon as React.ComponentType<{ className?: string }>;
    return <Icon className="h-4 w-4" />;
  }
  if (React.isValidElement(s.icon)) return s.icon;
  const key = (s.platform ?? s.label ?? "").toLowerCase();
  const Fallback = PLATFORM_ICONS[key] ?? Circle;
  return <Fallback className="h-4 w-4" />;
}

/**
 * Multi-column footer with brand block + link columns + bottom bar.
 * Accepts \`social\` (preferred) or \`socialLinks\` (alias). Each entry may
 * provide \`{ icon }\` or \`{ platform: "twitter" }\` \u2014 unknown platforms
 * fall back to a neutral icon.
 */
export function FooterColumns({
  brand,
  brandMark,
  logo,
  appName,
  tagline,
  description,
  columns,
  social,
  socialLinks,
  copyright,
  className,
}: {
  brand?: React.ReactNode;
  brandMark?: React.ReactNode;
  logo?: React.ReactNode;
  appName?: React.ReactNode;
  tagline?: React.ReactNode;
  description?: React.ReactNode;
  columns?: FooterColumn[];
  social?: SocialEntry[];
  socialLinks?: SocialEntry[];
  copyright?: React.ReactNode;
  className?: string;
}) {
  const socials = Array.isArray(social) && social.length > 0 ? social : Array.isArray(socialLinks) ? socialLinks : [];
  const cols = Array.isArray(columns) ? columns : [];
  const mark = brandMark ?? logo;
  const brandNode =
    brand ??
    (mark || appName ? (
      <span className="inline-flex items-center gap-2">
        {mark}
        {appName}
      </span>
    ) : null);
  const taglineNode = tagline ?? description;
  return (
    <footer className={cn("border-t border-border bg-muted/30 py-16", className)}>
      <Container size="xl">
        <div className="grid gap-10 md:grid-cols-12">
          <div className="md:col-span-4">
            {brandNode && <div className="text-base font-semibold text-foreground">{slotNode(brandNode)}</div>}
            {taglineNode && <p className="mt-2 max-w-xs text-sm text-muted-foreground">{taglineNode}</p>}

            {socials.length > 0 && (
              <div className="mt-5 flex gap-3">
                {socials.map((s, i) => (
                  <a
                    key={i}
                    href={s.href}
                    aria-label={s.label ?? s.platform ?? "social"}
                    className="flex h-9 w-9 items-center justify-center rounded-md border border-border bg-background text-muted-foreground transition hover:text-foreground"
                  >
                    {renderSocialIcon(s)}
                  </a>
                ))}
              </div>
            )}
          </div>
          <div className="grid grid-cols-2 gap-8 md:col-span-8 md:grid-cols-4">
            {cols.map((col, i) => (
              <div key={i}>
                <div className="text-xs font-semibold uppercase tracking-wider text-foreground">{col.title}</div>
                <ul className="mt-4 space-y-2.5">
                  {(col.links ?? []).map((l, j) => (
                    <li key={j}>
                      <a href={l.href} className="text-sm text-muted-foreground transition hover:text-foreground">
                        {l.label}
                      </a>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
        {copyright && (
          <div className="mt-12 border-t border-border pt-6 text-xs text-muted-foreground">{copyright}</div>
        )}
      </Container>
    </footer>
  );
}
`;
