    COUNT_UP = `"use client";
import * as React from "react";
import { motion, useInView, useMotionValue, useTransform, animate } from "framer-motion";

export interface CountUpProps extends React.HTMLAttributes<HTMLSpanElement> {
  to: number;
  from?: number;
  duration?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  once?: boolean;
}

export const CountUp: React.FC<CountUpProps> = ({
  to,
  from = 0,
  duration = 1.6,
  decimals = 0,
  prefix = "",
  suffix = "",
  once = true,
  ...rest
}) => {
  const ref = React.useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once, margin: "-10% 0px" });
  const value = useMotionValue(from);
  const rounded = useTransform(value, (v) => prefix + v.toFixed(decimals) + suffix);

  React.useEffect(() => {
    if (!inView) return;
    const controls = animate(value, to, { duration, ease: [0.22, 1, 0.36, 1] });
    return controls.stop;
  }, [inView, to, duration, value]);

  return (
    <motion.span ref={ref} {...rest}>
      {rounded}
    </motion.span>
  );
};
`;
    WORD_ROTATE = `"use client";
import * as React from "react";
import { AnimatePresence, motion } from "framer-motion";

export interface WordRotateProps {
  words: string[];
  interval?: number;
  className?: string;
}

export const WordRotate: React.FC<WordRotateProps> = ({
  words,
  interval = 2400,
  className,
}) => {
  const [i, setI] = React.useState(0);
  React.useEffect(() => {
    if (words.length <= 1) return;
    const id = window.setInterval(() => setI((p) => (p + 1) % words.length), interval);
    return () => window.clearInterval(id);
  }, [words.length, interval]);
  return (
    <span className={"inline-block overflow-hidden align-bottom " + (className ?? "")}>
      <AnimatePresence mode="wait">
        <motion.span
          key={words[i]}
          initial={{ y: "100%", opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: "-100%", opacity: 0 }}
          transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}
          className="inline-block"
        >
          {words[i]}
        </motion.span>
      </AnimatePresence>
    </span>
  );
};
`;
