    ROUTER = `/**
 * Thin, opinionated re-export of react-router-dom for the Kimble kit.
 *
 * Use this for any multi-page app. Define <Route> children once in App.tsx,
 * use <Link to="/about"> for navigation, useNavigate() for programmatic moves,
 * and useParams() for dynamic segments like "/post/:id".
 *
 * Common pattern (in App.tsx):
 *   import { Router, Routes, Route, Link, NavLink, Outlet } from "@/components/ui/router";
 *   <Router>
 *     <Routes>
 *       <Route element={<SiteLayout />}>
 *         <Route path="/" element={<HomePage />} />
 *         <Route path="/about" element={<AboutPage />} />
 *         <Route path="/post/:slug" element={<PostPage />} />
 *         <Route path="*" element={<NotFoundPage />} />
 *       </Route>
 *     </Routes>
 *   </Router>
 *
 * SiteLayout renders the shared header/footer and an <Outlet /> where the
 * matched child route is rendered. Use <NavLink> in headers \u2014 its
 * \`isActive\` render-prop child or \`className\` callback gives you free
 * active styling.
 */
import * as React from "react";
import { BrowserRouter as RRBrowserRouter, useNavigate } from "react-router-dom";

export {
  Routes,
  Route,
  Link,
  NavLink,
  Outlet,
  Navigate,
  RouterProvider,
  createBrowserRouter,
  createRoutesFromElements,
  useNavigate,
  useParams,
  useLocation,
  useSearchParams,
} from "react-router-dom";

/**
 * Intercepts clicks on plain internal <a href="/x"> links and routes them
 * client-side. Without this, any hand-written anchor in a nav, footer, or
 * card triggers a full page reload \u2014 the app flashes white and loses state.
 * External links, new-tab clicks, downloads, hash links, and mailto/tel are
 * left alone.
 */
function InternalLinkNavigation({ children }: { children?: React.ReactNode }) {
  const navigate = useNavigate();
  React.useEffect(() => {
    const onClick = (e: MouseEvent) => {
      if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      const target = e.target as HTMLElement | null;
      const anchor = target && typeof target.closest === "function" ? (target.closest("a") as HTMLAnchorElement | null) : null;
      if (!anchor) return;
      if (anchor.hasAttribute("download")) return;
      const anchorTarget = anchor.getAttribute("target");
      if (anchorTarget && anchorTarget !== "_self") return;
      const href = anchor.getAttribute("href");
      if (!href || href.startsWith("#") || href.startsWith("mailto:") || href.startsWith("tel:")) return;
      let url: URL;
      try {
        url = new URL(href, window.location.href);
      } catch {
        return;
      }
      if (url.origin !== window.location.origin) return;
      e.preventDefault();
      navigate(url.pathname + url.search + url.hash);
    };
    document.addEventListener("click", onClick);
    return () => document.removeEventListener("click", onClick);
  }, [navigate]);
  return <>{children}</>;
}

export function BrowserRouter({ children, ...props }: React.ComponentProps<typeof RRBrowserRouter>) {
  return (
    <RRBrowserRouter {...props}>
      <InternalLinkNavigation>{children}</InternalLinkNavigation>
    </RRBrowserRouter>
  );
}

export const Router = BrowserRouter;

export type { RouteObject } from "react-router-dom";

`;
