    CALENDAR = `import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";

/**
 * Minimal month-grid Calendar. No third-party deps.
 *   <Calendar mode="single" selected={date} onSelect={setDate} />
 *   <Calendar mode="range" selected={{from, to}} onSelect={setRange} />
 */
type SingleProps = {
  mode?: "single";
  selected?: Date;
  onSelect?: (d: Date | undefined) => void;
};
type RangeProps = {
  mode: "range";
  selected?: { from?: Date; to?: Date };
  onSelect?: (r: { from?: Date; to?: Date }) => void;
};
type CalendarProps = (SingleProps | RangeProps) & {
  className?: string;
  disabled?: (d: Date) => boolean;
  initialMonth?: Date;
};

const DAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

function startOfMonth(d: Date) { return new Date(d.getFullYear(), d.getMonth(), 1); }
function isSameDay(a?: Date, b?: Date) {
  if (!a || !b) return false;
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}
function isInRange(d: Date, from?: Date, to?: Date) {
  if (!from || !to) return false;
  const t = d.getTime();
  return t >= from.getTime() && t <= to.getTime();
}

export function Calendar(props: CalendarProps) {
  const { className, disabled, initialMonth } = props;
  const initial = initialMonth ?? (props.mode === "range" ? props.selected?.from : (props as SingleProps).selected) ?? new Date();
  const [view, setView] = React.useState(startOfMonth(initial));

  const month = view.getMonth();
  const year = view.getFullYear();
  const firstWeekday = view.getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const cells: Array<Date | null> = [];
  for (let i = 0; i < firstWeekday; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d));
  while (cells.length % 7 !== 0) cells.push(null);

  const monthLabel = view.toLocaleString("default", { month: "long", year: "numeric" });

  const handleSelect = (d: Date) => {
    if (disabled?.(d)) return;
    if (props.mode === "range") {
      const cur = props.selected;
      if (!cur?.from || (cur.from && cur.to)) {
        props.onSelect?.({ from: d, to: undefined });
      } else if (d.getTime() < cur.from.getTime()) {
        props.onSelect?.({ from: d, to: cur.from });
      } else {
        props.onSelect?.({ from: cur.from, to: d });
      }
    } else {
      props.onSelect?.(d);
    }
  };

  return (
    <div className={cn("p-3 pointer-events-auto", className)}>
      <div className="flex items-center justify-between pb-2">
        <button
          type="button"
          onClick={() => setView(new Date(year, month - 1, 1))}
          className="inline-flex h-7 w-7 items-center justify-center rounded-md hover:bg-accent"
          aria-label="Previous month"
        >
          <ChevronLeft className="h-4 w-4" />
        </button>
        <div className="text-sm font-medium">{monthLabel}</div>
        <button
          type="button"
          onClick={() => setView(new Date(year, month + 1, 1))}
          className="inline-flex h-7 w-7 items-center justify-center rounded-md hover:bg-accent"
          aria-label="Next month"
        >
          <ChevronRight className="h-4 w-4" />
        </button>
      </div>
      <div className="grid grid-cols-7 gap-1 text-center text-xs text-muted-foreground">
        {DAYS.map((d) => <div key={d} className="py-1">{d}</div>)}
      </div>
      <div className="mt-1 grid grid-cols-7 gap-1">
        {cells.map((d, i) => {
          if (!d) return <div key={i} />;
          const isDisabled = disabled?.(d) ?? false;
          let isSelected = false;
          let isInBetween = false;
          if (props.mode === "range") {
            isSelected = isSameDay(d, props.selected?.from) || isSameDay(d, props.selected?.to);
            isInBetween = isInRange(d, props.selected?.from, props.selected?.to) && !isSelected;
          } else {
            isSelected = isSameDay(d, (props as SingleProps).selected);
          }
          const isToday = isSameDay(d, new Date());
          return (
            <button
              key={i}
              type="button"
              disabled={isDisabled}
              onClick={() => handleSelect(d)}
              className={cn(
                "inline-flex h-9 w-9 items-center justify-center rounded-md text-sm",
                "hover:bg-accent hover:text-accent-foreground",
                isToday && !isSelected && "border border-border",
                isInBetween && "bg-accent/50",
                isSelected && "bg-primary text-primary-foreground hover:bg-primary",
                isDisabled && "opacity-40 pointer-events-none",
              )}
            >
              {d.getDate()}
            </button>
          );
        })}
      </div>
    </div>
  );
}
`;
    DATE_PICKER = `import * as React from "react";
import { Calendar as CalendarIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

/**
 * Drop-in date picker. Use whenever you need a single calendar field \u2014
 * NEVER hand-roll a custom date input.
 *   <DatePicker value={date} onChange={setDate} placeholder="Pick a date" />
 */
function format(d: Date) {
  return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}

export function DatePicker({
  value,
  onChange,
  placeholder = "Pick a date",
  disabled,
  className,
}: {
  value?: Date;
  onChange?: (d: Date | undefined) => void;
  placeholder?: string;
  disabled?: (d: Date) => boolean;
  className?: string;
}) {
  const [open, setOpen] = React.useState(false);
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          className={cn("w-[240px] justify-start text-left font-normal", !value && "text-muted-foreground", className)}
        >
          <CalendarIcon className="mr-2 h-4 w-4" />
          {value ? format(value) : <span>{placeholder}</span>}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        <Calendar
          mode="single"
          selected={value}
          onSelect={(d) => { onChange?.(d); setOpen(false); }}
          disabled={disabled}
        />
      </PopoverContent>
    </Popover>
  );
}
`;
    COMBOBOX = `import * as React from "react";
import { Check, ChevronsUpDown, Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

/**
 * Searchable single-select. Use whenever the user picks one option from a
 * long list (5+) \u2014 NEVER hand-roll a styled <select> for that case.
 *   <Combobox
 *     options={[{label:"Apple",value:"apple"}, ...]}
 *     value={picked}
 *     onChange={setPicked}
 *     placeholder="Pick a fruit"
 *   />
 */
export type ComboboxOption = { label: string; value: string };

export function Combobox({
  options,
  value,
  onChange,
  placeholder = "Select...",
  searchPlaceholder = "Search...",
  emptyText = "No results.",
  className,
}: {
  options: ComboboxOption[];
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  className?: string;
}) {
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const current = options.find((o) => o.value === value);
  const filtered = query
    ? options.filter((o) => o.label.toLowerCase().includes(query.toLowerCase()))
    : options;
  React.useEffect(() => { if (!open) setQuery(""); }, [open]);
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn("w-[240px] justify-between font-normal", !current && "text-muted-foreground", className)}
        >
          {current ? current.label : placeholder}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[240px] p-0" align="start">
        <div className="flex items-center border-b px-3">
          <Search className="mr-2 h-4 w-4 shrink-0 opacity-50" />
          <Input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={searchPlaceholder}
            className="h-9 border-0 px-0 focus-visible:ring-0 focus-visible:ring-offset-0"
          />
        </div>
        <div className="max-h-64 overflow-y-auto p-1" role="listbox">
          {filtered.length === 0 ? (
            <div className="px-2 py-6 text-center text-sm text-muted-foreground">{emptyText}</div>
          ) : (
            filtered.map((opt) => (
              <button
                key={opt.value}
                type="button"
                role="option"
                aria-selected={value === opt.value}
                onClick={() => { onChange?.(opt.value); setOpen(false); }}
                className="flex w-full cursor-pointer select-none items-center rounded-sm px-2 py-1.5 text-left text-sm outline-none hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:text-accent-foreground"
              >
                <Check className={cn("mr-2 h-4 w-4", value === opt.value ? "opacity-100" : "opacity-0")} />
                {opt.label}
              </button>
            ))
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}
`;
    FORM = `import * as React from "react";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

/**
 * Tiny form helper. NOT a react-hook-form clone \u2014 a thin wrapper that
 * gives you typed values, per-field errors, and submit handling without
 * any new dependencies.
 *
 *   const form = useForm({
 *     defaults: { email: "", password: "" },
 *     validate: (v) => ({
 *       email: !v.email.includes("@") ? "Invalid email" : undefined,
 *       password: v.password.length < 8 ? "Min 8 chars" : undefined,
 *     }),
 *     onSubmit: async (v) => { await api.signIn(v); },
 *   });
 *
 *   <Form onSubmit={form.handleSubmit}>
 *     <FormField name="email" label="Email" error={form.errors.email}>
 *       <Input {...form.register("email")} />
 *     </FormField>
 *     <Button type="submit" disabled={form.submitting}>Sign in</Button>
 *   </Form>
 *
 * For richer needs (async validation, arrays), graduate to react-hook-form.
 */
export type FormErrorMap<T> = { [K in keyof T]?: string };

export function useForm<T extends Record<string, unknown>>(opts: {
  /** Initial values. defaultValues is accepted as a react-hook-form alias. */
  defaults?: T;
  defaultValues?: T;
  validate?: (values: T) => FormErrorMap<T>;
  onSubmit?: (values: T) => void | Promise<void>;
}) {
  // Accept either spelling and never start from undefined: reading
  // values[name] off an undefined object crashes the whole page.
  const initial = (opts.defaults ?? opts.defaultValues ?? ({} as T)) as T;
  const [values, setValues] = React.useState<T>(initial);
  const [errors, setErrors] = React.useState<FormErrorMap<T>>({});
  const [touched, setTouched] = React.useState<Partial<Record<keyof T, boolean>>>({});
  const [submitting, setSubmitting] = React.useState(false);
  const [defaults, setDefaultsState] = React.useState<T>(initial);

  const setValue = React.useCallback(<K extends keyof T>(name: K, value: T[K]) => {
    setValues((prev) => ({ ...prev, [name]: value }));
  }, []);

  const register = React.useCallback(<K extends keyof T & string>(name: K) => ({
    name,
    value: ((values ?? ({} as T))[name] ?? "") as unknown as string,
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
      const next = e && e.target ? (e.target as HTMLInputElement).value : (e as unknown as string);
      setValue(name, next as unknown as T[K]);
    },
    onBlur: () => setTouched((t) => ({ ...t, [name]: true })),
  }), [values, setValue]);

  const submitValues = async (vals: T, handler?: (values: T) => void | Promise<void>) => {
    const errs = opts.validate?.(vals) ?? {};
    setErrors(errs);
    const allTouched = Object.keys(vals).reduce((acc, k) => ({ ...acc, [k]: true }), {});
    setTouched(allTouched as Partial<Record<keyof T, boolean>>);
    if (Object.values(errs).some((v) => v)) return;
    setSubmitting(true);
    try {
      await (handler ?? opts.onSubmit)?.(vals);
    } finally {
      setSubmitting(false);
    }
  };

  /**
   * Dual-mode, react-hook-form compatible:
   *   <form onSubmit={form.handleSubmit}>            // plain
   *   <form onSubmit={form.handleSubmit(onValid)}>   // RHF style
   */
  const handleSubmit: any = (arg?: any) => {
    if (typeof arg === "function") {
      return async (e?: React.FormEvent) => {
        e?.preventDefault?.();
        await submitValues(values, arg);
      };
    }
    const e = arg as React.FormEvent | undefined;
    e?.preventDefault?.();
    return submitValues(values);
  };

  const reset = (next?: T) => { setValues(next ?? defaults); setErrors({}); setTouched({}); };
  /** Re-seed the form (used when opening an "edit" dialog on a new record). */
  const setDefaults = (next: Partial<T>) => {
    const merged = { ...defaults, ...next } as T;
    setDefaultsState(merged);
    setValues(merged);
    setErrors({});
    setTouched({});
  };

  // A react-hook-form-shaped control object so shadcn-style
  // <FormField control={form.control} render=... /> binds to
  // the same state instead of rendering an inert, permanently-empty input.

  const control = React.useMemo(() => ({
    register: (name: string) => register(name as keyof T & string),
    _formValues: values,
    _defaultValues: defaults,
    _formState: { errors },
  }), [register, values, defaults, errors]);

  const formState = {
    isSubmitting: submitting,
    isDirty: JSON.stringify(values) !== JSON.stringify(defaults),
    isValid: Object.values(errors).every((v) => !v),
    errors,
  };

  return {
    __petalForm: true as const,
    values,
    errors,
    touched,
    submitting,
    isSubmitting: submitting,
    formState,
    control,
    defaultValues: defaults,
    setValue,
    setDefaults,
    getValues: () => values,
    watch: (name?: keyof T & string) => (name ? values[name] : values),
    setError: (name: keyof T, message: string) => setErrors((p) => ({ ...p, [name]: message })),
    clearErrors: () => setErrors({}),
    register,
    handleSubmit,
    reset,
  };
}

const PetalFormContext = React.createContext<any>(null);

/**
 * <Form> is dual-mode.
 *  - Plain mode:  <Form onSubmit={form.handleSubmit}> ... </Form>
 *  - Spread mode: <Form {...form}> ... </Form>          (our useForm object)
 *  - RHF mode:    <Form {...rhfForm}><form onSubmit={...}>\u2026</form></Form>
 *    A real react-hook-form object renders a transparent wrapper instead of a
 *    nested <form>, which would be invalid HTML and swallow the inner submit.
 */
export function Form(props: any) {
  const {
    className, children, control, handleSubmit, formState, watch, register,
    // Never leak form-object fields onto the DOM node.
    __petalForm, values, errors, touched, submitting, isSubmitting, setValue,
    setDefaults, getValues, setError, clearErrors, reset, defaultValues, onSubmit,
    ...rest
  } = props ?? {};

  // Our own useForm object was spread in: render a REAL form and wire submit,
  // otherwise the submit button is dead and the dialog never saves.
  if (__petalForm) {
    return (
      <PetalFormContext.Provider value={props}>
        <form
          className={cn("space-y-4", className)}
          onSubmit={(e) => { e.preventDefault(); (onSubmit ?? handleSubmit)?.(e); }}
          {...rest}
        >
          {children}
        </form>
      </PetalFormContext.Provider>
    );
  }

  const isRhf = Boolean(control || formState || (handleSubmit && watch));
  if (isRhf) return <>{children}</>;
  return <form className={cn("space-y-4", className)} onSubmit={onSubmit} {...rest}>{children}</form>;
}


function getRhfValue(control: any, name: string) {
  const values = control?._formValues ?? control?._defaultValues ?? {};
  return name.split(".").reduce((acc: any, key: string) => (acc == null ? acc : acc[key]), values);
}

/**
 * Controller-equivalent field binding without importing react-hook-form.
 * Subscribes to the form's value stream so \`field.value\` stays live \u2014
 * callers commonly render \`value={field.value}\`, and a static value would
 * make the input read as permanently empty.
 */
function useRhfField(control: any, name: string) {
  const [, force] = React.useReducer((c: number) => c + 1, 0);
  React.useEffect(() => {
    const subject = control?._subjects?.values ?? control?._subjects?.state ?? control?._subjects?.watch;
    if (!subject || typeof subject.subscribe !== "function") return;
    const sub = subject.subscribe({ next: () => force() });
    return () => {
      if (sub && typeof sub.unsubscribe === "function") sub.unsubscribe();
    };
  }, [control, name]);

  if (control && typeof control.register === "function") {
    try {
      const reg = control.register(name);
      const value = getRhfValue(control, name);
      return { ...reg, value: value === undefined || value === null ? "" : value };
    } catch {
      // fall through to the inert field below
    }
  }
  return {
    name,
    value: "",
    onChange: () => {},
    onBlur: () => {},
    ref: () => {},
  };
}

function getRhfError(control: any, name: string) {
  const errors = control?._formState?.errors ?? {};
  return name.split(".").reduce((acc: any, key: string) => (acc == null ? acc : acc[key]), errors);
}

/** Does this element look like a text-ish control we can bind to? */
function isBindableInput(el: any): boolean {
  const t = el?.type;
  if (t === "input" || t === "textarea" || t === "select") return true;
  const label = typeof t === "string" ? t : (t?.displayName ?? t?.name ?? "");
  return /^(Input|Textarea|TextArea|Select|NumberInput|PasswordInput|DatePicker)$/.test(label);
}

/**
 * Bind the first input-looking descendant to the form field. Generated pages
 * routinely write <FormField name="x"><FormControl><Input/></FormControl></FormField>
 * with no register() call \u2014 without this the input is inert and the form
 * submits empty values, which reads to the user as a dead form.
 */
function bindFieldChildren(node: React.ReactNode, reg: any, bound: { done: boolean }): React.ReactNode {
  return React.Children.map(node, (child: any) => {
    if (bound.done || !React.isValidElement(child)) return child;
    const props: any = child.props ?? {};
    if (isBindableInput(child)) {
      bound.done = true;
      if (props.value !== undefined || props.onChange !== undefined || props.defaultValue !== undefined) return child;
      return React.cloneElement(child, { ...reg, id: props.id ?? reg.name });
    }
    if (props.children) {
      return React.cloneElement(child, {
        children: bindFieldChildren(props.children, reg, bound),
      } as any);
    }
    return child;
  });
}

/**
 * FormField is dual-mode too.
 *  - Plain:  <FormField name="email" label="Email" error={...}><Input/></FormField>
 *  - RHF:    <FormField control={form.control} name="email" render={({ field }) => ...} />
 * Models write the shadcn/react-hook-form shape constantly; ignoring the
 * render prop silently drops the whole field from the page, so both work.
 */
export function FormField(props: any) {
  const { name, label, description, className, children, render } = props ?? {};
  const ctx = React.useContext(PetalFormContext);
  const control = props?.control ?? ctx?.control;
  const field = useRhfField(control, name);
  const error = props?.error ?? (name ? ctx?.errors?.[name] : undefined) ?? getRhfError(control, name);
  let body: React.ReactNode = children;
  if (typeof render === "function") {
    body = render({ field, fieldState: { error }, formState: ctx?.formState ?? control?._formState ?? {} });
  } else if (ctx && name) {
    body = bindFieldChildren(children, ctx.register(name), { done: false });
  }
  const errorText = typeof error === "string" ? error : error?.message;
  return (
    <div className={cn("space-y-1.5", className)}>
      {label && <Label htmlFor={name}>{label}</Label>}
      {body}
      {description && !errorText && <p className="text-xs text-muted-foreground">{description}</p>}
      {errorText && <p className="text-xs text-destructive">{errorText}</p>}
    </div>
  );
}


/** Summary of submit-time errors. Safe to render with no props. */
export function FormErrors({ errors, className }: { errors?: Record<string, any>; className?: string }) {
  const list = Object.values(errors ?? {})
    .map((e: any) => (typeof e === "string" ? e : e?.message))
    .filter(Boolean) as string[];
  if (list.length === 0) return null;
  return (
    <div className={cn("rounded-md border border-destructive/30 bg-destructive/10 p-3", className)} role="alert">
      {list.map((msg, i) => (
        <p key={i} className="text-sm text-destructive">{msg}</p>
      ))}
    </div>
  );
}

// shadcn-compatible aliases so generated code never hits a missing export.
export function FormItem({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("space-y-1.5", className)} {...props} />;
}
export function FormLabel(props: React.ComponentProps<typeof Label>) {
  return <Label {...props} />;
}
export function FormControl({ children }: { children?: React.ReactNode }) {
  return <>{children}</>;
}
export function FormDescription({ className, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cn("text-xs text-muted-foreground", className)} {...props} />;
}
export function FormMessage({ className, children }: { className?: string; children?: React.ReactNode }) {
  if (!children) return null;
  return <p className={cn("text-xs text-destructive", className)}>{children}</p>;
}
`;
    DRAWER = `import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * Bottom-anchored drawer (mobile-first). Sibling to <Sheet>. Use this
 * for mobile detail panels and action sheets where you want a draggable
 * handle and rounded top corners.
 *
 *   <Drawer open={open} onOpenChange={setOpen}>
 *     <DrawerContent>
 *       <DrawerHeader>
 *         <DrawerTitle>Filters</DrawerTitle>
 *         <DrawerDescription>Refine the list below.</DrawerDescription>
 *       </DrawerHeader>
 *       <div className="px-4 pb-4">...</div>
 *       <DrawerFooter>
 *         <Button>Apply</Button>
 *       </DrawerFooter>
 *     </DrawerContent>
 *   </Drawer>
 */
type Ctx = { open: boolean; setOpen: (v: boolean) => void };
const DrawerContext = React.createContext<Ctx | null>(null);

export function Drawer({
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  children,
}: {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (v: boolean) => void;
  children: React.ReactNode;
}) {
  const [internal, setInternal] = React.useState(defaultOpen);
  const open = controlled ?? internal;
  const setOpen = (v: boolean) => {
    if (controlled === undefined) setInternal(v);
    onOpenChange?.(v);
  };
  return <DrawerContext.Provider value={{ open, setOpen }}>{children}</DrawerContext.Provider>;
}

export function DrawerTrigger({ asChild: _asChild, children }: { asChild?: boolean; children: React.ReactElement }) {
  const ctx = React.useContext(DrawerContext);
  if (!ctx) throw new Error("DrawerTrigger must be inside Drawer");
  return React.cloneElement(children, { onClick: () => ctx.setOpen(true) } as React.HTMLAttributes<HTMLElement>);
}

export function DrawerClose({ asChild: _asChild, children }: { asChild?: boolean; children: React.ReactElement }) {
  const ctx = React.useContext(DrawerContext);
  if (!ctx) throw new Error("DrawerClose must be inside Drawer");
  return React.cloneElement(children, { onClick: () => ctx.setOpen(false) } as React.HTMLAttributes<HTMLElement>);
}

export function DrawerContent({ className, children, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  const ctx = React.useContext(DrawerContext);
  React.useEffect(() => {
    if (!ctx?.open) return;
    const onEsc = (e: KeyboardEvent) => { if (e.key === "Escape") ctx.setOpen(false); };
    document.addEventListener("keydown", onEsc);
    return () => document.removeEventListener("keydown", onEsc);
  }, [ctx]);
  if (!ctx?.open) return null;
  return (
    <>
      <div className="fixed inset-0 z-50 bg-black/50" onClick={() => ctx.setOpen(false)} />
      <div
        role="dialog"
        className={cn(
          "fixed inset-x-0 bottom-0 z-50 mt-24 flex max-h-[85vh] flex-col rounded-t-[12px] border bg-background",
          "animate-in slide-in-from-bottom",
          className,
        )}
        {...props}
      >
        <div className="mx-auto mt-2 h-1.5 w-12 shrink-0 rounded-full bg-muted" />
        {children}
      </div>
    </>
  );
}

export function DrawerHeader({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("grid gap-1.5 p-4 text-center sm:text-left", className)} {...props} />;
}
export function DrawerTitle({ className, ...props }: React.HTMLAttributes<HTMLHeadingElement>) {
  return <h2 className={cn("text-lg font-semibold", className)} {...props} />;
}
export function DrawerDescription({ className, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cn("text-sm text-muted-foreground", className)} {...props} />;
}
export function DrawerFooter({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("mt-auto flex flex-col gap-2 p-4", className)} {...props} />;
}
`;
    CHART = `import * as React from "react";
import { cn } from "@/lib/utils";

/**
 * Lightweight pure-SVG charts. Zero dependencies. For cases the kit
 * doesn't cover (treemaps, radial), graduate to recharts manually.
 *
 *   <LineChart data={[{x:"Mon",y:120}, ...]} className="h-48" />
 *   <AreaChart data={[...]} />
 *   <BarChart data={[...]} />
 *
 * All three accept the same props. Colors come from semantic tokens
 * via CSS variables on the wrapping ChartContainer (--chart-1 etc.).
 */
export type ChartPoint = {
  x?: string | number;
  y?: number;
  /** Aliases accepted so common data shapes just work. */
  label?: string | number;
  name?: string | number;
  value?: number;
  count?: number;
  total?: number;
};

/** Accept {x,y}, {label,value}, {name,value}, {label,count} \u2014 never render NaN. */
function normalizePoints(data: ChartPoint[] | undefined | null): { x: string | number; y: number }[] {
  return (Array.isArray(data) ? data : []).map((d) => {
    const raw = d ?? ({} as ChartPoint);
    const yRaw = raw.y ?? raw.value ?? raw.count ?? raw.total;
    const y = typeof yRaw === "number" && Number.isFinite(yRaw) ? yRaw : 0;
    const x = raw.x ?? raw.label ?? raw.name ?? "";
    return { x, y };
  });
}
export type ChartProps = React.HTMLAttributes<HTMLDivElement> & {
  data: ChartPoint[];
  /** 1..5 \u2014 selects the semantic chart color token. */
  color?: 1 | 2 | 3 | 4 | 5;
  /** Show x-axis labels. */
  xAxis?: boolean;
  /** Show y-axis ticks. */
  yAxis?: boolean;
};

const DEFAULT_COLORS: Record<number, string> = {
  1: "var(--primary)",
  2: "oklch(0.65 0.18 200)",
  3: "oklch(0.6 0.2 30)",
  4: "oklch(0.65 0.15 140)",
  5: "oklch(0.6 0.18 320)",
};

function useDimensions(data: { y: number }[]) {
  const max = Math.max(1, ...data.map((d) => d.y));
  const min = Math.min(0, ...data.map((d) => d.y));
  return { max, min };
}

export function ChartContainer({ className, children, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={cn("relative h-64 w-full", className)} {...props}>
      {children}
    </div>
  );
}

export function LineChart({ data: rawData, color = 1, xAxis = true, className, ...props }: ChartProps) {
  const data = normalizePoints(rawData);
  const { max, min } = useDimensions(data);
  const stroke = DEFAULT_COLORS[color];
  const w = 100;
  const h = 100;
  const pad = 4;
  const points = data.map((d, i) => {
    const x = pad + (i * (w - pad * 2)) / Math.max(1, data.length - 1);
    const y = h - pad - ((d.y - min) / (max - min || 1)) * (h - pad * 2);
    return [x, y] as const;
  });
  const path = points.map(([x, y], i) => (i === 0 ? \`M\${x},\${y}\` : \`L\${x},\${y}\`)).join(" ");
  return (
    <ChartContainer className={className} {...props}>
      <svg viewBox={\`0 0 \${w} \${h}\`} preserveAspectRatio="none" className="h-full w-full">
        <path d={path} fill="none" stroke={stroke} strokeWidth={1.5} vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
      {xAxis && (
        <div className="mt-1 flex justify-between text-[10px] text-muted-foreground">
          {data.map((d, i) => <span key={i}>{d.x}</span>)}
        </div>
      )}
    </ChartContainer>
  );
}

export function AreaChart({ data: rawData, color = 1, xAxis = true, className, ...props }: ChartProps) {
  const data = normalizePoints(rawData);
  const { max, min } = useDimensions(data);
  const stroke = DEFAULT_COLORS[color];
  const w = 100;
  const h = 100;
  const pad = 4;
  const points = data.map((d, i) => {
    const x = pad + (i * (w - pad * 2)) / Math.max(1, data.length - 1);
    const y = h - pad - ((d.y - min) / (max - min || 1)) * (h - pad * 2);
    return [x, y] as const;
  });
  const linePath = points.map(([x, y], i) => (i === 0 ? \`M\${x},\${y}\` : \`L\${x},\${y}\`)).join(" ");
  const areaPath = \`\${linePath} L\${points[points.length - 1][0]},\${h - pad} L\${points[0][0]},\${h - pad} Z\`;
  const id = React.useId();
  return (
    <ChartContainer className={className} {...props}>
      <svg viewBox={\`0 0 \${w} \${h}\`} preserveAspectRatio="none" className="h-full w-full">
        <defs>
          <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={stroke} stopOpacity={0.4} />
            <stop offset="100%" stopColor={stroke} stopOpacity={0} />
          </linearGradient>
        </defs>
        <path d={areaPath} fill={\`url(#\${id})\`} />
        <path d={linePath} fill="none" stroke={stroke} strokeWidth={1.5} vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
      {xAxis && (
        <div className="mt-1 flex justify-between text-[10px] text-muted-foreground">
          {data.map((d, i) => <span key={i}>{d.x}</span>)}
        </div>
      )}
    </ChartContainer>
  );
}

export function BarChart({ data: rawData, color = 1, xAxis = true, className, ...props }: ChartProps) {
  const data = normalizePoints(rawData);
  const { max } = useDimensions(data);
  const fill = DEFAULT_COLORS[color];
  const w = 100;
  const h = 100;
  const pad = 4;
  const slot = (w - pad * 2) / Math.max(1, data.length);
  const barW = Math.max(1, slot * 0.65);
  return (
    <ChartContainer className={className} {...props}>
      <svg viewBox={\`0 0 \${w} \${h}\`} preserveAspectRatio="none" className="h-full w-full">
        {data.map((d, i) => {
          const x = pad + i * slot + (slot - barW) / 2;
          const barH = ((d.y / (max || 1)) * (h - pad * 2));
          const y = h - pad - barH;
          return <rect key={i} x={x} y={y} width={barW} height={Math.max(0, barH)} rx={0.5} fill={fill} />;
        })}
      </svg>
      {xAxis && (
        <div className="mt-1 flex justify-between text-[10px] text-muted-foreground">
          {data.map((d, i) => <span key={i}>{d.x}</span>)}
        </div>
      )}
    </ChartContainer>
  );
}
`;
