      content: `// Auto-generated by Kimble. SERVER-ONLY \u2014 never import from a React component.
//
// process.env.STRIPE_SECRET_KEY is injected by Kimble at build time from the
// credentials you supplied in the Integrations marketplace. Do NOT hardcode
// keys here.

const STRIPE_SECRET_KEY =
  (typeof process !== "undefined" ? process.env.STRIPE_SECRET_KEY : undefined) ?? "";
const DEFAULT_CURRENCY =
  (typeof process !== "undefined" ? process.env.STRIPE_CURRENCY : undefined) ?? "usd";

export type CheckoutLineItem = {
  /** Human-readable product name shown on the Stripe-hosted page. */
  name: string;
  /** Amount in the SMALLEST currency unit (cents for USD, pence for GBP). */
  amountMinor: number;
  quantity: number;
  /** Optional currency override per line item. Defaults to STRIPE_CURRENCY. */
  currency?: string;
  /** Optional product description. */
  description?: string;
};

export type CreateCheckoutInput = {
  items: CheckoutLineItem[];
  successUrl: string;
  cancelUrl: string;
  /** "payment" for one-off, "subscription" for recurring. Defaults to payment. */
  mode?: "payment" | "subscription";
  /** Optional customer email to pre-fill. */
  customerEmail?: string;
  /** Free-form metadata stored on the Stripe Session and echoed in webhooks. */
  metadata?: Record<string, string>;
};

export type CheckoutResult =
  | { ok: true; url: string; sessionId: string }
  | { ok: false; error: string };

export async function createCheckoutSession(
  input: CreateCheckoutInput,
): Promise<CheckoutResult> {
  if (!STRIPE_SECRET_KEY) {
    return { ok: false, error: "STRIPE_SECRET_KEY is not configured" };
  }
  if (!input.items.length) {
    return { ok: false, error: "At least one line item is required" };
  }

  // Stripe accepts form-encoded bodies for this endpoint.
  const body = new URLSearchParams();
  body.set("mode", input.mode ?? "payment");
  body.set("success_url", input.successUrl);
  body.set("cancel_url", input.cancelUrl);
  if (input.customerEmail) body.set("customer_email", input.customerEmail);

  input.items.forEach((item, i) => {
    body.set(\`line_items[\${i}][quantity]\`, String(item.quantity));
    body.set(\`line_items[\${i}][price_data][currency]\`, item.currency ?? DEFAULT_CURRENCY);
    body.set(\`line_items[\${i}][price_data][unit_amount]\`, String(item.amountMinor));
    body.set(\`line_items[\${i}][price_data][product_data][name]\`, item.name);
    if (item.description) {
      body.set(\`line_items[\${i}][price_data][product_data][description]\`, item.description);
    }
  });

  if (input.metadata) {
    for (const [k, v] of Object.entries(input.metadata)) {
      body.set(\`metadata[\${k}]\`, v);
    }
  }

  const res = await fetch("https://api.stripe.com/v1/checkout/sessions", {
    method: "POST",
    headers: {
      Authorization: \`Bearer \${STRIPE_SECRET_KEY}\`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });

  if (!res.ok) {
    const errText = await res.text().catch(() => res.statusText);
    return { ok: false, error: \`Stripe API \${res.status}: \${errText}\` };
  }
  const data = (await res.json()) as { id: string; url: string };
  return { ok: true, url: data.url, sessionId: data.id };
}
`
