      content: `// Auto-generated by Kimble. SERVER-ONLY.
//
// Verify the \`Stripe-Signature\` header on the RAW request body. Stripe signs
// "{timestamp}.{rawBody}" with HMAC-SHA256 using the webhook signing secret.
// Tolerance: reject events older than 5 minutes (replay protection).

import { createHmac, timingSafeEqual } from "node:crypto";

const WEBHOOK_SECRET =
  (typeof process !== "undefined" ? process.env.STRIPE_WEBHOOK_SECRET : undefined) ?? "";

export type StripeEvent = {
  id: string;
  type: string;
  data: { object: Record<string, unknown> };
  created: number;
};

export type WebhookResult =
  | { ok: true; event: StripeEvent }
  | { ok: false; error: string; status: number };

export function verifyStripeWebhook(
  rawBody: string,
  signatureHeader: string | null,
  toleranceSeconds = 300,
): WebhookResult {
  if (!WEBHOOK_SECRET) return { ok: false, error: "STRIPE_WEBHOOK_SECRET not configured", status: 500 };
  if (!signatureHeader) return { ok: false, error: "Missing Stripe-Signature header", status: 400 };

  // Header format: t=<unix>,v1=<sig>,v1=<sig>...
  const parts = Object.fromEntries(
    signatureHeader.split(",").map((p) => {
      const [k, ...rest] = p.split("=");
      return [k, rest.join("=")];
    }),
  ) as Record<string, string>;

  const timestamp = Number(parts.t);
  const provided = parts.v1;
  if (!timestamp || !provided) return { ok: false, error: "Malformed signature", status: 400 };

  const nowSec = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSec - timestamp) > toleranceSeconds) {
    return { ok: false, error: "Signature timestamp outside tolerance", status: 400 };
  }

  const expected = createHmac("sha256", WEBHOOK_SECRET)
    .update(\`\${timestamp}.\${rawBody}\`)
    .digest("hex");

  const a = Buffer.from(expected);
  const b = Buffer.from(provided);
  if (a.length !== b.length || !timingSafeEqual(a, b)) {
    return { ok: false, error: "Invalid signature", status: 401 };
  }

  try {
    const event = JSON.parse(rawBody) as StripeEvent;
    return { ok: true, event };
  } catch {
    return { ok: false, error: "Invalid JSON body", status: 400 };
  }
}
`
