//
// Flutterwave does NOT use HMAC for webhooks. Instead, you set a "secret
// hash" in the dashboard, and Flutterwave sends it back verbatim in the
// \`verif-hash\` header. We compare in constant time.

import { timingSafeEqual } from "node:crypto";

const SECRET_HASH =
  (typeof process !== "undefined" ? process.env.FLUTTERWAVE_WEBHOOK_SECRET_HASH : undefined) ?? "";

export type FlutterwaveEvent = {
  event: string;
  /** Flutterwave's "data" payload. \`id\` is the transaction id you re-verify with. */
  data: Record<string, unknown> & {
    id?: number;
    tx_ref?: string;
    status?: string;
    amount?: number;
    currency?: string;
  };
};

export type WebhookResult =
  | { ok: true; event: FlutterwaveEvent }
  | { ok: false; error: string; status: number };

export function verifyFlutterwaveWebhook(
  rawBody: string,
  hashHeader: string | null,
): WebhookResult {
  if (!SECRET_HASH)
    return { ok: false, error: "FLUTTERWAVE_WEBHOOK_SECRET_HASH not configured", status: 500 };
  if (!hashHeader) return { ok: false, error: "Missing verif-hash header", status: 400 };

  const a = Buffer.from(SECRET_HASH);
  const b = Buffer.from(hashHeader);
  if (a.length !== b.length || !timingSafeEqual(a, b)) {
    return { ok: false, error: "Invalid verif-hash", status: 401 };
  }

  try {
    const event = JSON.parse(rawBody) as FlutterwaveEvent;
    return { ok: true, event };
  } catch {
    return { ok: false, error: "Invalid JSON body", status: 400 };
  }
}
