      content: `// Auto-generated by Kimble. Browser helper to launch Stripe Identity.
// Requires \`bun add @stripe/stripe-js\`.
import { loadStripe } from "@stripe/stripe-js";

const PUBLISHABLE_KEY = import.meta.env.VITE_STRIPE_IDENTITY_PUBLISHABLE_KEY as string | undefined;

export async function launchIdentityVerification(opts: { returnUrl: string; bearerToken: string }) {
  if (!PUBLISHABLE_KEY) throw new Error("VITE_STRIPE_IDENTITY_PUBLISHABLE_KEY missing");
  const stripe = await loadStripe(PUBLISHABLE_KEY);
  if (!stripe) throw new Error("Stripe.js failed to load");
  const res = await fetch("/api/identity/start", {
    method: "POST",
    headers: { authorization: \`Bearer \${opts.bearerToken}\`, "content-type": "application/json" },
    body: JSON.stringify({ returnUrl: opts.returnUrl }),
  });
  if (!res.ok) throw new Error(\`could not start verification (\${res.status})\`);
  const { clientSecret } = (await res.json()) as { clientSecret: string };
  const { error } = await stripe.verifyIdentity(clientSecret);
  if (error) throw error;
}
`
