function messageText(content) {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content.map(
      (p2) => typeof p2 === "object" && p2 && "text" in p2 ? String(p2.text) : ""
    ).join(" ");
  }
  return "";
}
